function Counter() {
  const [count, setCount] = useState(0);
  const scheduleBonus = () => {
    setTimeout(() => setCount(count + 10), 3000); // 💀 count bị đóng băng
  };
  return <button onClick={scheduleBonus}>+10 sau 3s (hiện: {count})</button>;
}

